{
  "headline": "FDA's records trace our supply to plants with OAI classifications and a Warning Letter within the past year",
  "headline_cites": ["E32", "E33"],
  "sentences": [
    {
      "text": "The Baxter Healthcare Corporation plant that manufactures insulin glulisine for our Baxter-labeled product received an OAI classification on 2026-04-02 and a Warning Letter on 2026-09-29.",
      "cites": ["E32", "E33"]
    },
    {
      "text": "The Sanofi-Aventis Deutschland GmbH plant that manufactures insulin glulisine for our Sanofi-labeled product received an OAI classification on 2010-09-16 and a Warning Letter on 2011-02-08.",
      "cites": ["E17", "E24"]
    },
    {
      "text": "Corvale East has 17 days of insulin glulisine on hand, Corvale General has 21 days, and Corvale Lakeside has 17 days.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "Eli Lilly and Company's Indianapolis plant is not on FDA's shortage list for insulin glulisine as of today.",
      "cites": ["E58"]
    },
    {
      "text": "The best option by rule is to buy from Eli Lilly and Company.",
      "cites": ["E58"]
    }
  ]
}
